32	    /** A claim's due as its row shows it: the due fixed when it was settled, else the one its last statement bound
33	     *  it to as shown then (late charge and floor included; n/a included), else its floored figure (the greater of the
34	     *  floor in force on its date and its live figure) with the late charge worked out on that floored figure added (a
35	     *  correction, a negative amount, has no floor and no charge); null (n/a) when it has no figure. */
36	    public static BigDecimal shown(Claim claim, Grades grades, Rates rates, DatedAmount floor,
37	            LateCharge late) {
38	        if (claim.settledDue() != null) {
39	            return claim.settledDue();
40	        }
41	        if (claim.stated()) {
42	            return claim.statedDue();
43	        }
44	        BigDecimal figure = figure(claim, grades, rates, late.rounding());
45	        if (figure == null || claim.amount().signum() < 0) {
46	            return figure;
47	        }
