53	     *  rates that reach it: a forward-only rate only reaches claims added after it), divided by 100, rounded to two
54	     *  decimals as the claim rounds (see Rounding); null (n/a) when no rate applies. */
55	    public static BigDecimal live(Claim claim, Grades grades, Rates rates, Rounding rounding) {
56	        return rates.on(claim.sheetId(), grades.on(claim.date()), claim.date(), claim.id())
57	                .map(r -> claim.amount().multiply(r.pct()).divide(BigDecimal.valueOf(100), 2, rounding.of(claim)))
58	                .orElse(null);
59	    }
