61	    /** Whether a claim counts toward its person's figures and every live total: an OPEN, PENDING or SETTLED one,
62	     *  except an OPEN or PENDING one not bound by a statement once its person's retirement date is reached (see
63	     *  retiredOut), and one deferred on the sheet's today (see Claim.deferredOn). A hold (the claim's own or its
64	     *  person's) does not take a claim out of any total; it only takes the person out of the pools' cuts. */
65	    public static boolean counts(Claim claim, Holds holds, LocalDate retiredFrom, LocalDate today) {
66	        return claim.status().counts() && !claim.deferredOn(today)
67	                && !retiredOut(claim, retiredFrom, today);
68	    }
69	
70	    /** Whether a claim counts toward claimed and the claimed-total: as it counts (see counts). */
71	    public static boolean countsClaimed(Claim claim, LocalDate retiredFrom, LocalDate today) {
