76	     *  retirement date (null: not retired) and it is OPEN or PENDING and not bound by a statement. */
77	    private static boolean retiredOut(Claim claim, LocalDate retiredFrom, LocalDate today) {
78	        return retiredFrom != null && today != null && !today.isBefore(retiredFrom) && !claim.stated()
79	                && (claim.status() == ClaimStatus.OPEN || claim.status() == ClaimStatus.PENDING);
80	    }
