96	            LocalDate retiredFrom, LocalDate today, Rates rates, DatedAmount floor, LateCharge late) {
97	        List<Claim> counted = claims.stream().filter(c -> counts(c, holds, retiredFrom, today)).toList();
98	        List<BigDecimal> figures = counted.stream().map(c -> shown(c, grades, rates, floor, late))
99	                .filter(f -> f != null).toList();
100	        if (figures.isEmpty() && rates.on(sheetId, grades.on(today), today).isEmpty()) {
101	            return null;
102	        }
103	        return figures.stream().reduce(new BigDecimal("0.00"), BigDecimal::add);
