344	
345	    /** The proof kinds a proof can be: a receipt (when none is chosen) or a photo. */
346	    public static final java.util.List<String> PROOF_KINDS = java.util.List.of("receipt", "photo");
347	
348	    /** How many of its proofs are of the kind: photos, or receipts (the rest). */
349	    public int proofsOf(String kind) {
350	        return "photo".equals(kind) ? photos : "receipt".equals(kind) ? proofs - photos : 0;
351	    }
352	
353	    /** Whether the claim is deferred on the sheet's today: it is OPEN and deferred until a date after today (null:
354	     *  no today, nothing is deferred). Deferred, it counts in no total, is not overdue, cannot be settled and is
355	     *  left unbound by a statement; from that date on it is an OPEN claim like any other. */
356	    public boolean deferredOn(LocalDate today) {
357	        return status == ClaimStatus.OPEN && deferredUntil != null && today != null && deferredUntil.isAfter(today);
358	    }
