package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.Grades;
import net.officefloor.hq.app.person.Holds;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.DatedAmount;

/** Claim figures and due-totals, as the screen shows them. */
public final class Dues {
    private Dues() {
    }

    /** A claim's figure: the due fixed when it was settled, else the one its last statement bound it to, n/a
     *  included (an OPEN or PENDING one alike), else live: its amount times its person's rate in force on
     *  its date for their grade then, divided by 100, rounded to two decimals as the claim rounds (see Rounding); null
     *  (n/a) when no rate applies. The floor is not in it: it is applied before the late charge (see shown). */
    public static BigDecimal figure(Claim claim, Grades grades, Rates rates, Rounding rounding) {
        if (claim.settledDue() != null) {
            return claim.settledDue();
        }
        if (claim.stated()) {
            return claim.statedDue();
        }
        return live(claim, grades, rates, rounding);
    }

    /** A claim's due as its row shows it: the due fixed when it was settled, else the one its last statement bound
     *  it to as shown then (late charge and floor included; n/a included), else its floored figure (the greater of the
     *  floor in force on its date and its live figure) with the late charge worked out on that floored figure added (a
     *  correction, a negative amount, has no floor and no charge); null (n/a) when it has no figure. */
    public static BigDecimal shown(Claim claim, Grades grades, Rates rates, DatedAmount floor,
            LateCharge late) {
        if (claim.settledDue() != null) {
            return claim.settledDue();
        }
        if (claim.stated()) {
            return claim.statedDue();
        }
        BigDecimal figure = figure(claim, grades, rates, late.rounding());
        if (figure == null || claim.amount().signum() < 0) {
            return figure;
        }
        BigDecimal floored = figure.max(floor.on(claim.date()));
        return floored.add(late.on(claim, floored));
    }

    /** A claim's live figure: its amount times its person's rate in force on its date for their grade then (of the
     *  rates that reach it: a forward-only rate only reaches claims added after it), divided by 100, rounded to two
     *  decimals as the claim rounds (see Rounding); null (n/a) when no rate applies. */
    public static BigDecimal live(Claim claim, Grades grades, Rates rates, Rounding rounding) {
        return rates.on(claim.sheetId(), grades.on(claim.date()), claim.date(), claim.id())
                .map(r -> claim.amount().multiply(r.pct()).divide(BigDecimal.valueOf(100), 2, rounding.of(claim)))
                .orElse(null);
    }

    /** Whether a claim counts toward its person's figures and every live total: an OPEN, PENDING or SETTLED one,
     *  except an OPEN or PENDING one not bound by a statement once its person's retirement date is reached (see
     *  retiredOut), and one deferred on the sheet's today (see Claim.deferredOn). A hold (the claim's own or its
     *  person's) does not take a claim out of any total; it only takes the person out of the pools' cuts. */
    public static boolean counts(Claim claim, Holds holds, LocalDate retiredFrom, LocalDate today) {
        return claim.status().counts() && !claim.deferredOn(today)
                && !retiredOut(claim, retiredFrom, today);
    }

    /** Whether a claim counts toward claimed and the claimed-total: as it counts (see counts). */
    public static boolean countsClaimed(Claim claim, LocalDate retiredFrom, LocalDate today) {
        return claim.status().counts() && !claim.deferredOn(today) && !retiredOut(claim, retiredFrom, today);
    }

    /** Whether a claim leaves the live totals because its person is retired: the sheet's today is on or after their
     *  retirement date (null: not retired) and it is OPEN or PENDING and not bound by a statement. */
    private static boolean retiredOut(Claim claim, LocalDate retiredFrom, LocalDate today) {
        return retiredFrom != null && today != null && !today.isBefore(retiredFrom) && !claim.stated()
                && (claim.status() == ClaimStatus.OPEN || claim.status() == ClaimStatus.PENDING);
    }

    /** Whether a claim counts toward a period's due-totals: its status at the end of the period's last day (see
     *  ClaimLogRepository.statusesAt; null: it was added after) is OPEN, PENDING or SETTLED, and it is left out
     *  as the live rules leave it out: deferred on the sheet's today, or an OPEN or PENDING one of a retired person
     *  (see counts). */
    public static boolean countsAtEnd(Claim claim, ClaimStatus atEnd, Holds holds, LocalDate retiredFrom,
            LocalDate today) {
        return atEnd != null && atEnd.counts() && !claim.deferredOn(today)
                && !retiredOut(claim, retiredFrom, today);
    }

    /** A person's due-total: the dues (as shown) of their claims that count added up, skipping n/a; null (n/a) when
     *  their grade today has no rate today, unless a claim that counts has a figure (settled, stated, or live at
     *  the grade in force on its date). */
    public static BigDecimal total(String sheetId, List<Claim> claims, Grades grades, Holds holds,
            LocalDate retiredFrom, LocalDate today, Rates rates, DatedAmount floor, LateCharge late) {
        List<Claim> counted = claims.stream().filter(c -> counts(c, holds, retiredFrom, today)).toList();
        List<BigDecimal> figures = counted.stream().map(c -> shown(c, grades, rates, floor, late))
                .filter(f -> f != null).toList();
        if (figures.isEmpty() && rates.on(sheetId, grades.on(today), today).isEmpty()) {
            return null;
        }
        return figures.stream().reduce(new BigDecimal("0.00"), BigDecimal::add);
    }

    /** A holder's part of a claim's due: the due times their share divided by 100, rounded half to even to two
     *  decimals. */
    public static BigDecimal part(BigDecimal due, BigDecimal share) {
        return due.multiply(share).divide(BigDecimal.valueOf(100), 2, java.math.RoundingMode.HALF_EVEN);
    }

    /** The cap less a person's cut total (null: none), not below 0.00; null when there is no cap. */
    public static BigDecimal capLess(BigDecimal cap, BigDecimal cut) {
        return cap == null || cut == null ? cap : cap.subtract(cut).max(BigDecimal.ZERO.setScale(2));
    }

    /** A due-total at most the sheet's cap (null: none); n/a (null) is not capped. */
    public static BigDecimal capped(BigDecimal total, BigDecimal cap) {
        return total != null && cap != null ? total.min(cap) : total;
    }
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Grades;
import net.officefloor.hq.app.person.Holds;
import net.officefloor.hq.app.person.InvalidPersonException;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonResponse;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.DatedAmount;
import net.officefloor.hq.app.setting.SettingHistory;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Take the person's statement: record their due-total now (late charges included, at most the sheet's cap) and the sheet's today, bind
 *  each of their claims that counts to its due as shown now (late charge and floor included: while bound it no longer
 *  follows the sheet's today; one already bound is bound again to the figure it shows), and unbind the rest (their due is live again; a claim deferred on today is left unbound). A settled claim's
 *  fixed due is left as it is.
 *  <p>Taken as of a date (on or before the sheet's today; refused after it, or for a person added after it), the
 *  same is done with the sheet as it stood at the end of that date: every change made while the sheet's today was on
 *  or before it counts, every later one does not, and the date stands in for the sheet's today. Their claims that
 *  counted then are bound to their dues as shown then, the rest are unbound, and the date is recorded as the statement's. */
public class SaveStatement {
    public void save(@Val StatementRequest request, @Val Person loaded, PersonRepository people,
            ClaimRepository claims, RateRepository rates, SheetRepository sheets, SettingRepository settings,
            Out<Statement> statement, Out<PersonResponse> saved) throws InvalidPersonException {
        people.lock(loaded);
        Person person = people.find(loaded.sheetId(), loaded.id());
        String sheetId = person.sheetId();
        LocalDate today = sheets.today(sheetId);
        LocalDate asOf = request.asOf() != null ? LocalDate.parse(request.asOf()) : null;
        if (asOf != null && today != null && asOf.isAfter(today)) {
            throw new InvalidPersonException("A statement cannot be taken as of a date after the sheet's today ("
                    + today + ").");
        }
        if (asOf != null && !people.addedBy(person, asOf)) {
            throw new InvalidPersonException(person.name() + " was not on the sheet on " + asOf + ".");
        }
        LocalDate on = asOf != null ? asOf : today;
        List<Claim> theirs = claims.listForPerson(sheetId, person.id());
        Rounding now = Rounding.of(sheetId, settings, sheets, claims);

        List<Claim> then;
        Grades grades;
        Holds holds;
        LocalDate retiredFrom;
        Rates ratesThen;
        DatedAmount floor;
        LateCharge late;
        BigDecimal cap;
        if (asOf == null) {
            then = theirs;
            grades = person.grades();
            holds = person.holds();
            retiredFrom = person.retiredFrom();
            ratesThen = rates;
            floor = settings.floor(sheetId);
            late = LateCharge.of(sheetId, settings, sheets, claims, people);
            cap = settings.cap(sheetId);
        } else {
            then = claims.listForPersonAsOf(sheetId, person.id(), asOf);
            grades = people.gradesAsOf(person, asOf);
            holds = people.holdsAsOf(person, asOf);
            retiredFrom = people.retiredFromAsOf(person, asOf);
            ratesThen = rates.asOf(sheetId, asOf);
            SettingHistory history = settings.historyAsOf(sheetId, asOf);
            floor = history::floorOn;
            LocalDate policy = settings.policyDate(sheetId);
            late = new LateCharge(history::latePctOn, asOf, new Rounding(policy != null ? policy : asOf,
                    now.numbered(), history.of(SettingHistory.ROUNDING)), LateCharge.Grace.of(history, Map.of(person.id(), grades)));
            cap = history.capOn(asOf);
        }

        BigDecimal total = Dues.capped(Dues.total(sheetId, then, grades, holds, retiredFrom, on, ratesThen, floor,
                late), cap);
        Map<Long, BigDecimal> bound = new HashMap<>();
        for (Claim c : then) {
            if (Dues.counts(c, holds, retiredFrom, on)) {
                bound.put(c.id(), Dues.shown(c, grades, ratesThen, floor, late));
            }
        }
        for (Claim c : theirs) {
            if (bound.containsKey(c.id())) {
                claims.state(c, true, bound.get(c.id()));
            } else if (c.stated()) {
                claims.state(c, false, null);
            }
        }
        people.stated(person, total, on);
        statement.set(new Statement(sheetId, person.name(), total, bound.size(), asOf));
        saved.set(PersonResponse.from(people.find(sheetId, person.id())));
    }
}
package net.officefloor.hq.app.statement;

import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.InvalidPersonException;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonResponse;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Cancel the person's last statement: only a steward may, and only of a person with a statement. The claims it
 *  bound become live again (a figure an earlier statement bound them to is not restored), there is one statement
 *  fewer, and the row shows the one before it (or none). Publishes the cancelled statement (its due-total; the
 *  claims it bound). */
public class CancelStatement {
    public void cancel(@Val StatementRequest request, @Val Person loaded, PersonRepository people,
            ClaimRepository claims, RoleRepository roles, Out<Statement> statement, Out<PersonResponse> saved)
            throws InvalidPersonException {
        if (!Role.STEWARD.equals(roles.of(loaded.sheetId(), request.user()))) {
            throw new InvalidPersonException("Only a steward may cancel a statement.");
        }
        people.lock(loaded);
        Person person = people.find(loaded.sheetId(), loaded.id());
        if (person.statementCount() == 0) {
            throw new InvalidPersonException(person.name() + " has no statement to cancel.");
        }
        int bound = 0;
        for (Claim c : claims.listForPerson(person.sheetId(), person.id())) {
            if (c.stated()) {
                bound++;
                claims.state(c, false, null);
            }
        }
        people.unstated(person);
        statement.set(new Statement(person.sheetId(), person.name(), person.statedTotal(), bound, null));
        saved.set(PersonResponse.from(people.find(person.sheetId(), person.id())));
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Defer the loaded claim until the date: only an OPEN claim, and only to a date after the sheet's today (a
 *  deferred claim may be deferred again). A deferral another user's change got to first is refused. */
public class SaveDefer {
    public void save(@Val DeferInput input, @Val Claim loaded, SheetRepository sheets, ClaimRepository repository,
            Out<ClaimResponse> saved) throws ClaimStatusNotAllowedException, InvalidClaimException {
        if (loaded.status() != ClaimStatus.OPEN) {
            throw new ClaimStatusNotAllowedException("A " + loaded.status()
                    + " claim cannot be deferred; only an OPEN one can.");
        }
        var today = sheets.today(loaded.sheetId());
        if (today == null || !input.until().isAfter(today)) {
            throw new InvalidClaimException("Defer the claim to a date after the sheet's today (" + today + ").");
        }
        if (!repository.defer(loaded, input.until())) {
            throw new ClaimStatusNotAllowedException("The claim changed meanwhile; load the sheet again.");
        }
        saved.set(ClaimResponse.from(new Claim(loaded.id(), loaded.sheetId(), loaded.personId(), loaded.amount(),
                loaded.date(), loaded.note(), loaded.status(), loaded.number(), loaded.settledDue(),
                loaded.openedBy(), loaded.stated(), loaded.statedDue(), loaded.corrects(), loaded.dueBy(),
                input.until(), loaded.proofs(), loaded.splitFrom(), loaded.lateEntry(), loaded.reminded(), loaded.ref(), loaded.tags(), loaded.waived(), loaded.photos(), loaded.held()), List.of(), today));
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read: a signed-in user and a date (yyyy-mm-dd) to defer until. */
public class ValidateDefer {
    public void validate(@RequestBody DeferRequest request, Out<DeferInput> body) throws InvalidClaimException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidClaimException("Sign in before changing claims.");
        }
        LocalDate until;
        try {
            until = LocalDate.parse(request.until() == null ? "" : request.until().trim());
        } catch (DateTimeParseException e) {
            throw new InvalidClaimException("Give the date to defer the claim until as yyyy-mm-dd.");
        }
        body.set(new DeferInput(request.user().trim(), until));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A person's claim: an amount (two decimals; below 0.00 only for a correction), a date, a note (may be empty), its
 *  status, its number (sheet-wide digits as given before fiscal-year numbering, FY<yyyy>-<n> within the tree's fiscal year, or <period name>-<n> / X-<n> when numbered within its period; null while a draft; a voided claim keeps the one it had) and, once settled, the due fixed
 *  at settling (null before then, or when the person's grade had no rate then: its due stays live), and
 *  who opened it (null while a draft), whether its person's last statement bound it (it counted then) and the
 *  due as shown then it bound it to, late charge included (null when not bound, or it was n/a then), and for a correction
 *  (a negative amount) the number of the SETTLED claim of the same person it corrects (null otherwise), and its
 *  due-by: the terms-th business day after the date it had when it was created, with the terms fixed then (its person's
 *  own, else their grade's in force on that date, else the sheet's), skipping Saturdays, Sundays and the sheet's
 *  holidays as they are now; it does not change when the terms or its date change later; and the date it is deferred until (null: never
 *  deferred): an OPEN claim deferred past the sheet's today is deferred (see deferredOn); and its proofs count (0 or more,
 *  raised one at a time); and the number of the claim it was split from (null when it was not split off one); and whether it is a
 *  late entry: added while its period was soft-closed (fixed when it was added); and the last sheet-today a reminder was
 *  written for it (null: never reminded); and its external reference (null: none), unique on the sheet without regard to case;
 *  and its tags (null: none): trimmed, lower-cased, without repeats, sorted and joined by commas; and whether a steward waived its late charge
 *  (it then bears none, overdue or not); and how many of its proofs are photos (the rest are receipts); and whether it is held
 *  (only an OPEN or PENDING claim is held or released): held, an OPEN one not bound by a statement counts in no live
 *  total, as one dated within its person's hold does (see Dues.counts). */
public record Claim(long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
        ClaimStatus status, String number, BigDecimal settledDue, String openedBy, boolean stated,
        BigDecimal statedDue, String corrects, LocalDate dueBy, LocalDate deferredUntil, int proofs,
        String splitFrom, boolean lateEntry, LocalDate reminded, String ref,
        String tags, boolean waived, int photos, boolean held) {

    /** The proof kinds a proof can be: a receipt (when none is chosen) or a photo. */
    public static final java.util.List<String> PROOF_KINDS = java.util.List.of("receipt", "photo");

    /** How many of its proofs are of the kind: photos, or receipts (the rest). */
    public int proofsOf(String kind) {
        return "photo".equals(kind) ? photos : "receipt".equals(kind) ? proofs - photos : 0;
    }

    /** Whether the claim is deferred on the sheet's today: it is OPEN and deferred until a date after today (null:
     *  no today, nothing is deferred). Deferred, it counts in no total, is not overdue, cannot be settled and is
     *  left unbound by a statement; from that date on it is an OPEN claim like any other. */
    public boolean deferredOn(LocalDate today) {
        return status == ClaimStatus.OPEN && deferredUntil != null && today != null && deferredUntil.isAfter(today);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.List;

/** A claim as the screen shows it: the amount with two decimals, the date as yyyy-mm-dd, the status, its
 *  number (null when it has none) and the due fixed when it was settled (two decimals; null when it is not
 *  settled, or its grade had no rate then, so its due follows the rates), who opened it (null while a draft),
 *  whether its person's last statement bound it and the figure it bound it to (two decimals; null when not
 *  bound, or n/a then), and the number a correction corrects (null when it is not one), and its due-by as yyyy-mm-dd,
 *  and its status log, oldest first (empty when not loaded with it), and the date it is deferred until as yyyy-mm-dd
 *  (null when never deferred) and whether it is deferred on the sheet's today (see Claim.deferredOn; false when
 *  shown without a today), and its proofs count, and the number of the claim it was split from (null when
 *  it was not split off one), and whether it is a late entry, and the last day it was reminded as yyyy-mm-dd (null when never), and its external reference (null when none), and its tags, sorted (empty when none), and its comments, oldest first, as <user> on <date>: <text> (empty when not
 *  loaded with them), and the number of the settle batch that settled it (null when none settled it), and its lines, in the
 *  order added, as <label> <qty> x <unit> (empty when not loaded with them), and its review day as yyyy-mm-dd: the
 *  sheet's today when it went to REVIEW (null when it never did, or not loaded with it), and whether its late charge was waived, and how many of its proofs are of each kind (receipt, photo), and whether it is held, and its shares, in the order added (empty when none, or not loaded with them), and the user a steward assigned to review it (null when none,
 *  or not loaded with it), and its pending day as yyyy-mm-dd: the sheet's today when it last went to PENDING (null when it
 *  never did, or not loaded with it). */
public record ClaimResponse(long id, long personId, String amount, String date, String note, String status,
        String number, String settledDue, String openedBy, boolean stated, String statedDue, String corrects, String dueBy,
        List<String> log, String deferredUntil, boolean deferred, int proofs, String splitFrom, boolean lateEntry, String reminded, String ref,
        List<String> tags, List<String> comments, Integer batch, List<String> lines, String reviewOn,
        boolean waived, java.util.Map<String, Integer> proofKinds, boolean held, List<ClaimShareRepository.Share> shares,
        String reviewer, String pendingOn) {
    public static ClaimResponse from(Claim c) {
        return from(c, List.of(), null);
    }

    public static ClaimResponse from(Claim c, List<String> log, LocalDate today) {
        return from(c, log, today, List.of());
    }

    public static ClaimResponse from(Claim c, List<String> log, LocalDate today, List<String> comments) {
        return from(c, log, today, comments, null);
    }

    public static ClaimResponse from(Claim c, List<String> log, LocalDate today, List<String> comments,
            Integer batch) {
        return from(c, log, today, comments, batch, List.of());
    }

    public static ClaimResponse from(Claim c, List<String> log, LocalDate today, List<String> comments,
            Integer batch, List<String> lines) {
        return from(c, log, today, comments, batch, lines, null);
    }

    public static ClaimResponse from(Claim c, List<String> log, LocalDate today, List<String> comments,
            Integer batch, List<String> lines, LocalDate reviewOn) {
        return new ClaimResponse(c.id(), c.personId(), c.amount().toPlainString(), c.date().toString(), c.note(),
                c.status().name(), c.number(), c.settledDue() != null ? c.settledDue().toPlainString() : null,
                c.openedBy(), c.stated(), c.statedDue() != null ? c.statedDue().toPlainString() : null,
                c.corrects(), c.dueBy().toString(), log,
                c.deferredUntil() != null ? c.deferredUntil().toString() : null, c.deferredOn(today), c.proofs(),
                c.splitFrom(), c.lateEntry(), c.reminded() != null ? c.reminded().toString() : null, c.ref(),
                c.tags() != null ? List.of(c.tags().split(",")) : List.of(), comments, batch, lines,
                reviewOn != null ? reviewOn.toString() : null, c.waived(), proofKinds(c), c.held(), List.of(), null, null);
    }

    /** This claim as shown with its shares, in the order added. */
    public ClaimResponse withShares(List<ClaimShareRepository.Share> shares) {
        return new ClaimResponse(id, personId, amount, date, note, status, number, settledDue, openedBy, stated,
                statedDue, corrects, dueBy, log, deferredUntil, deferred, proofs, splitFrom, lateEntry, reminded, ref,
                tags, comments, batch, lines, reviewOn, waived, proofKinds, held, shares, reviewer, pendingOn);
    }

    /** This claim as shown with the user assigned to review it (null when none). */
    public ClaimResponse withReviewer(String reviewer) {
        return new ClaimResponse(id, personId, amount, date, note, status, number, settledDue, openedBy, stated,
                statedDue, corrects, dueBy, log, deferredUntil, deferred, proofs, splitFrom, lateEntry, reminded, ref,
                tags, comments, batch, lines, reviewOn, waived, proofKinds, held, shares, reviewer, pendingOn);
    }

    /** This claim as shown with its pending day (null when it never went to PENDING). */
    public ClaimResponse withPendingOn(LocalDate pendingOn) {
        return new ClaimResponse(id, personId, amount, date, note, status, number, settledDue, openedBy, stated,
                statedDue, corrects, dueBy, log, deferredUntil, deferred, proofs, splitFrom, lateEntry, reminded, ref,
                tags, comments, batch, lines, reviewOn, waived, proofKinds, held, shares, reviewer,
                pendingOn != null ? pendingOn.toString() : null);
    }

    /** How many of its proofs are of each proof kind, in the order of the kinds. */
    private static java.util.Map<String, Integer> proofKinds(Claim c) {
        var kinds = new java.util.LinkedHashMap<String, Integer>();
        Claim.PROOF_KINDS.forEach(k -> kinds.put(k, c.proofsOf(k)));
        return kinds;
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.sheet.AsOf;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** The sheet's claims, newest first, each with its status log and its comments and its lines and whether it is deferred on the sheet's today and the settle batch that settled it and its review day and its shares and the user assigned to review it and its pending day; given
 *  an as-of date, as they stood at the end of it, with their logs and comments then and deferred on it; given a preview
 *  date, as they are now, deferred on it. */
public class RespondWithClaims {
    public void respond(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "asOf", required = false) String asOf,
            @RequestParam(name = "preview", required = false) String preview, ClaimRepository repository,
            ClaimLogRepository logs, ClaimCommentRepository comments, ClaimLineRepository claimLines, ClaimShareRepository claimShares, SheetRepository sheets, SettleBatchRepository batches,
            ObjectResponse<List<ClaimResponse>> response) {
        String id = sheetId.trim();
        LocalDate end = AsOf.parse(asOf);
        Map<Long, List<String>> lines = logs.lines(id, end);
        Map<Long, List<String>> said = comments.lines(id, end);
        Map<Long, List<String>> lined = claimLines.lines(id, end);
        Map<Long, List<ClaimShareRepository.Share>> shared = claimShares.shares(id, end);
        Map<Long, Integer> settledBy = batches.byClaim(id);
        Map<Long, LocalDate> reviewDays = repository.reviewDays(id);
        Map<Long, String> reviewers = repository.reviewers(id);
        Map<Long, LocalDate> pendingDays = repository.pendingDays(id);
        LocalDate on = AsOf.figuredOn(end, preview);
        var today = on != null ? on : sheets.today(id);
        List<Claim> claims = end != null ? repository.listAsOf(id, end) : repository.list(id);
        response.send(claims.stream()
                .map(c -> ClaimResponse.from(c, lines.getOrDefault(c.id(), List.of()), today,
                        said.getOrDefault(c.id(), List.of()), batchOf(c, settledBy),
                        lined.getOrDefault(c.id(), List.of()), reviewDays.get(c.id()))
                        .withShares(shared.getOrDefault(c.id(), List.of()))
                        .withReviewer(reviewers.get(c.id()))
                        .withPendingOn(pendingDays.get(c.id()))).toList());
    }

    /** The batch that settled the claim, shown while it is PENDING or SETTLED; null otherwise. */
    private static Integer batchOf(Claim c, Map<Long, Integer> settledBy) {
        return c.status() == ClaimStatus.PENDING || c.status() == ClaimStatus.SETTLED ? settledBy.get(c.id()) : null;
    }
}

