  expect(await ui.setRate(pg_wes, {"grade": "A", "pct": "33.33", "from": "2026-03-16", "to": "2026-03-12"})).toBe(false);
  expect(await ui.bulkSettle(pg_wes, [c_cam_2, c_cam_0])).toEqual({ settled: 2, refused: 0 });
  await ui.refresh(pg_wes);
